function records(type, includeArchived = true) { const rows = dataset?.tables?.[type] || []; return includeArchived ? rows : rows.filter(r => !archived(r)); }
function findRecord(type,id) { return (type==='cages'?cageRecords():records(type)).find(r => String(r[entity[type].id])===String(id)); }
function mouseName(id) { const m=findRecord('mice',id); return m ? `${m.physical_tag || 'Untagged'} · ${id}` : `SID ${id} · not in workspace`; }
function parentState(mouse) { const s=ids(mouse.sire_sids),d=ids(mouse.dam_sids); return s.length>1||d.length>1?'Ambiguous':s.length||d.length?'Recorded':'Not recorded'; }
function cageRecords() {
 const direct=records('cages').map(r=>({...r})),seen=new Set(direct.map(r=>String(r.cage_sid)));
 for(const m of records('mice')) if(m.cage_sid&&!seen.has(String(m.cage_sid))){seen.add(String(m.cage_sid));direct.push({cage_sid:String(m.cage_sid),cage_tag:m.cage_tag||null,record_origin:'derived_mouse_reference',_derived:true})}
 return direct;
}
function managerFor(type,record){return type==='cages'?model.cageManager(record,records('mice')):model.mouseManager(record)}
