function renderWelcome() {
 $('main').innerHTML=`<section class="welcome"><span class="eyebrow">Braintime Mouse Data</span><h2>Manage your colony.</h2><p>Mice, breeding, cages and light history.</p><div class="actions">${cloud.configured?button(cloud.signedIn?'Open shared colony':'Sign in',cloud.signedIn?'cloud-pull':'settings',true):button('Import records','import',true)}${button('Try demo','demo')}${button('Start empty','empty-workspace')}</div></section><div class="welcome-steps"><article><span class="step-number">1</span><h3>Bring your records</h3><p>Import your reconstructed JSON.</p></article><article><span class="step-number">2</span><h3>Share with your lab</h3>${button('Connect cloud','settings')}</article><article><span class="step-number">3</span><h3>Install on any device</h3>${button('Install & help','help')}</article></div>`;
}
function demoBanner(){return dataset?.demo||dataset?.is_demo||dataset?.synthetic?'<div class="banner demo"><strong>Demo data</strong> · Invented animals</div>':''}
function stat(value,label,note,key){return `<article class="stat"${key?` data-overview-count="${key}"`:''}><div class="stat-label">${esc(label)}</div><div class="stat-value">${typeof value==='number'?count(value):esc(value)}</div><div class="stat-note">${esc(note)}</div></article>`}
function overviewStatsHTML(){
 const summary=summarizeOverview(dataset,{asOf:localDate()}),display=metric=>metric.estimated?`≈${count(metric.count)}`:metric.unknown?(metric.count?`≥${count(metric.count)}`:'—'):count(metric.count);
 const cards=[
  ['living',summary.livingMice,'Living mice','Current Stock animals'],
  ['groups',summary.activeGroups,'Active breeding groups','Currently recorded active'],
  ['litters',display(summary.unweanedLitters),'Unweaned litters',summary.unweanedLitters.unknown?'Review litter dates and state':'Current unweaned litters'],
  ['cages',display(summary.cagesInUse),'Cages in use',summary.cagesInUse.unknown?'Cage assignments incomplete':'Occupied by living mice'],
  ['breedingCages',display(summary.breedingCages),'Breeding cages',summary.breedingCages.unknown?'Review breeding assignments':'Active breeders housed together'],
  ['locoboxes',display(summary.locoboxes),'Locoboxes in use',summary.locoboxes.estimated?'Includes current Animal Sheet estimates':summary.locoboxes.unknown?'Review housing and cage options':'Ani Beh + SHLAC Rat room']
 ];
 return `<section class="overview-activity" aria-labelledby="overview-activity-heading"><div class="mouse-summary-heading"><h2 id="overview-activity-heading">Current activity</h2><button class="text-button" data-action="overview-help" aria-label="Help with current Animal Overview counts">Help</button></div><div class="grid stats overview-stats">${cards.map(([key,value,label,note])=>stat(value,label,note,key)).join('')}</div></section>`;
}
function overviewHelpHTML(){return `<p class="subtle">Animal Overview shows currently recorded activity, excluding archived records and historical totals. Living mice are current Stock animals. Active breeding groups exclude future setup dates and groups already disbanded. Unweaned litters require an Unweaned state and a birth date on or before today, without an effective weaning or end date. Missing or conflicting dates and states remain uncertain. These counts describe the recorded database; unrecorded activity cannot be counted.</p><p class="subtle">Cages in use counts distinct cages assigned to living mice. Breeding cages counts each current cage with living males and females together. Breeding groups also includes nonoverlapping current Animal Sheet mixed-sex estimates. Historical registrations and conflicting source identities stay separate for review. Review uncertain assignments in Breeding and Mice.</p><p class="subtle">SHLAC Rat room cages count as LocoBoxes. Ani Beh cages also count unless marked Temporary storage in Cage type or excluded by position in Cages → Options. The default is one box per occupied cage; shared boxes can be grouped by Locobox ID. Current Animal Sheet positions with recognizable animal tags contribute estimates without creating mouse assignments. ≈ includes these estimates; ≥ is a recorded minimum while assignments are incomplete; — means unknown. Housing records and capacity settings are managed under Cages and Housing &amp; light. Historical records remain available in their tables and Source archive.</p>`}

function renderOverview() {
 const stock=records('mice',false).filter(m=>m.state==='Stock'&&!m.archived),known=stock.filter(m=>parentState(m)!=='Not recorded'),amb=stock.filter(m=>parentState(m)==='Ambiguous');
 const recent=stock.filter(m=>m.date_of_birth&&m.date_of_birth<=localDate()).sort((a,b)=>String(b.date_of_birth).localeCompare(String(a.date_of_birth))).slice(0,6);
 const lines=new Map();for(const m of stock)lines.set(m.mouseline||'Unspecified',1+(lines.get(m.mouseline||'Unspecified')||0));
 $('main').innerHTML=demoBanner()+`${overviewStatsHTML()}<div class="dashboard-grid"><div>${panel('Recently born',recent.length?recent.map(m=>`<div class="line-item"><div><button class="record-link" data-open="mice" data-id="${esc(m.mouse_sid)}">${esc(m.physical_tag||`Mouse ${m.mouse_sid}`)}</button><div class="small muted">${esc(m.mouseline||'Line not recorded')} · ${esc(m.sex||'Unknown sex')}</div></div><div style="text-align:right">${esc(m.date_of_birth)}<div>${badge(m.state||'Unknown',m.state==='Stock'?'green':'')}</div></div></div>`).join(''):'<p class="subtle">No birth dates recorded for living mice.</p>',button('View mice','view-mice'))}${panel('Quick actions',`<div class="settings-actions" style="margin-top:0">${canEditRecords()?button('Register mouse','new-mice',true)+button('Set up breeding','new-matings')+button('Record litter','new-litters'):''}${button('View family tree','family')}${button('Plan a cross','planner')}</div><p class="small muted" style="margin:16px 0 0">Validated records · Preserved sources</p>`)}</div><div>${panel('Pedigree coverage',`<strong style="font-size:24px;font-weight:500">${count(known.length)} <span class="muted" style="font-size:13px">of ${count(stock.length)} Stock mice</span></strong><p class="subtle" style="margin-top:9px">have at least one currently recorded parent role.</p><div class="coverage-meter"><span style="width:${stock.length?known.length/stock.length*100:0}%"></span></div><p class="small muted">${count(amb.length)} living mice have candidate parents.</p>`,button('Open tree','family'))}${panel('Stock by mouseline',[...lines.entries()].sort((a,b)=>b[1]-a[1]).slice(0,8).map(([line,total])=>`<div class="line-item"><span>${esc(line)}</span><strong>${count(total)}</strong></div>`).join('')||'<p class="subtle">No Stock mice.</p>')}${panel('Workspace',kv([['Storage',cloud.mode==='cloud'?'Shared cloud':'This browser only'],['Living mice',stock.length],['Source snapshot',dataset.as_of_local_date],['Source files',dataset.sources?.length||0]]))}</div></div>`;
}
function profileLoci(record){return Array.isArray(record.genetic_profile?.loci)?record.genetic_profile.loci.filter(locus=>locus&&typeof locus==='object'&&typeof locus.id==='string').map(locus=>({...locus,name:typeof locus.name==='string'?locus.name:locus.id})):[]}
function usableAlleleCall(call){return Array.isArray(call?.alleles)&&call.alleles.length===2&&call.alleles.every(allele=>typeof allele==='string')&&['confirmed','inferred'].includes(call.evidence)}
function alleleSummary(record){return profileLoci(record).map(locus=>{const call=record.genetic_profile.calls?.[locus.id];return `${locus.name||locus.id}: ${usableAlleleCall(call)?call.alleles.join('/'):'unknown'}${call?.evidence==='inferred'?' (inferred)':''}`}).join('; ')}
function columnValue(record,key) {
 if(key==='genotype')return alleleSummary(record)||record.genotype;
 if(key==='_housing')return cageHousing(record).housing;
 if(key==='_manager')return managerText(managerFor(route,record));
 if(key==='_parents')return parentState(record);
 if(key==='_linked')return records('mice',false).filter(m=>String(m.litter_sid)===String(record.litter_sid)).length;
 if(key==='_stock')return records('mice',false).filter(m=>m.state==='Stock'&&String(m.cage_sid)===String(record.cage_sid)).length;
 if(key==='_origin')return record._derived?'Derived reference':record.record_origin==='app_created'?'Created in app':'Recorded cage';
 return record[key];
}
function filteredRecords() {
 const data=route==='cages'?cageRecords():records(route);let result=data.filter(r=>(filters.archived||!archived(r))&&Object.entries(filters).every(([k,v])=>k==='archived'||!v||(k==='_strain_code'?mouseStrains(r)[v.split(':')[1]]===v.split(':')[0]:String(columnValue(r,k)??'')===v)));
 const terms=query.toLowerCase().trim().split(/\s+/).filter(Boolean);result=result.filter(r=>terms.every(t=>(JSON.stringify(r)+' '+(['mice','cages'].includes(route)?columnValue(r,'_manager'):'')+' '+(route==='cages'?cageHousing(r).housing:'')).toLowerCase().includes(t)));
 if(sortKey)result.sort((a,b)=>{const av=columnValue(a,sortKey),bv=columnValue(b,sortKey);if(av==null)return bv==null?0:1;if(bv==null)return-1;const cmp=String(av).localeCompare(String(bv),undefined,{numeric:true});return sortDesc?-cmp:cmp});
 return result;
}
function selectFilter(key,label,values){return `<label class="sr-only" for="filter-${key}">${esc(label)}</label><select id="filter-${key}" data-filter="${key}"><option value="">${esc(label)}</option>${values.map(v=>`<option value="${esc(v)}"${filters[key]===v?' selected':''}>${esc(v)}</option>`).join('')}</select>`}
function mouseStrains(mouse){
 if(strainIndexDataset!==dataset){const genes=new Map();for(const row of records('mouse_genes')){const sid=String(row.mouse_sid);if(!genes.has(sid))genes.set(sid,[]);genes.get(sid).push(row)}strainAssignments=new Map(records('mice').map(row=>[String(row.mouse_sid),mouseLineAssignments(row,genes.get(String(row.mouse_sid))||[])]));strainIndexDataset=dataset}
 return strainAssignments.get(String(mouse.mouse_sid))||{};
}
function strainCodeFilter(){return `<label class="sr-only" for="filter-_strain_code">Strain code</label><select id="filter-_strain_code" data-filter="_strain_code"><option value="">All strain codes</option>${['recorded','uncertain'].map(status=>`<optgroup label="${status==='recorded'?'Recorded strains':'Undetermined until genotyping'}">${getStrainRegistry(dataset).map(({key,name})=>{const value=status+':'+key;return `<option value="${esc(value)}"${filters._strain_code===value?' selected':''}>${esc(status==='recorded'?key:`(${key})`)} · ${esc(name)}</option>`}).join('')}</optgroup>`).join('')}</select>`}
function strainTypeLabel(value){return {transgenic:'Transgenic (random insertion)',knock_in:'Knock-in',unknown:'Unknown'}[value]||'Unknown'}
function strainLegendHTML(){return `${strainNamingHelpHTML()}<div class="table-scroll"><table class="strain-legend"><thead><tr><th>Code</th><th>Strain / construct</th><th>Insertion type</th></tr></thead><tbody>${getStrainRegistry(dataset).map(row=>`<tr><td><strong>${esc(row.key)}</strong></td><td>${esc(row.name)}</td><td>${esc(strainTypeLabel(row.insertionType))}</td></tr>`).join('')}</tbody></table></div><p class="subtle">An apostrophe (′ or ') means homozygous. Parentheses mean undetermined until genotyping: P′ is homozygous PER2::LUC; (P) has undetermined P status; P(′) has undetermined homozygosity. Combined codes describe several lines in one mouse, such as PB′. Vg and Gt are case-sensitive; Vg is distinct from V. WT means wild type. An unprimed code alone does not establish a two-allele call.</p><p class="subtle">P/E/B/F/V/AD are in the current Animal Sheet legend; A/32/96/Vg/Gt also appear in archived legends. Use Mice → Strains to edit insertion type, stock reference and notes. Insertion type is separate from zygosity.</p><p class="subtle">AD: the Animal Sheet references JAX 005864, Tg(APPswe,PSEN1dE9)85Dbo. <a href="https://www.informatics.jax.org/allele/MGI%3A3524957" target="_blank" rel="noopener noreferrer">MGI transgene reference</a>.</p>`}
async function openStrains(){let dialog=$('strain-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='strain-dialog';document.body.appendChild(dialog)}dialog.innerHTML='<div class="dialog-heading"><h2>Strains &amp; acronyms</h2><button class="icon-button" id="strain-close" aria-label="Close strains">×</button></div><div class="dialog-content" id="strain-management"></div>';$('strain-close').onclick=()=>dialog.close();dialog.showModal();await renderStrainManagement($('strain-management'),dataset,{canEdit:()=>canEditRecords('genetics'),saveDataset:async next=>{if(!canEditRecords('genetics'))throw new Error('Read-only access.');await store.saveDataset(next);dataset=await store.loadDataset();render()},reloadDataset:async()=>{dataset=await store.loadDataset();render();return dataset},toast:showToast})}
function mouseSummaryHTML(){
 const summary=summarizeMice(dataset);
 const items=[['alive','Alive','Current colony',summary.alive,summary.unknownSex?`${count(summary.unknownSex)} with unknown sex`:'All current Stock mice'],['sex','Male | Female','',`${count(summary.male)} | ${count(summary.female)}`,'Current male and female mice'],...MOUSE_LINE_GROUPS.map(({key,name})=>[key,key,name,summary.totalLines[key],`${name}: ${count(summary.lines[key])} recorded + ${count(summary.uncertainLines[key])} undetermined`,summary.uncertainLines[key]])];
 const combinations=buildFamilyGenotypes(dataset,{scope:'current'}).combinations.map(group=>({label:group.label,count:group.count}));
 const missing=summary.alive-combinations.reduce((sum,group)=>sum+group.count,0);
 if(missing>0){const unclassified=combinations.find(group=>group.label==='Unclassified');if(unclassified)unclassified.count+=missing;else combinations.push({label:'Unclassified',count:missing})}
 return `<section class="mouse-summary" aria-labelledby="mouse-summary-heading"><div class="mouse-summary-heading"><h2 id="mouse-summary-heading">Current living colony</h2><div class="actions">${button('Strains','strains')}<button class="text-button" data-action="mouse-count-help" aria-label="Help with current mouse counts">Help</button></div></div><dl class="mouse-summary-grid">${items.map(([key,label,name,total,title,uncertain])=>`<div class="mouse-summary-item${key==='alive'?' mouse-summary-total':key==='sex'?' mouse-summary-sex':''}" data-mouse-count="${key}" title="${esc(title)}"><dt>${esc(label)}${name?`<span>${esc(name)}</span>`:''}</dt><dd>${key==='sex'?esc(total):count(total)}</dd>${uncertain?`<span class="mouse-count-uncertain">${count(uncertain)} undetermined</span>`:''}</div>`).join('')}</dl><details class="source-disclosure"><summary>Genotype combinations (${count(combinations.length)})</summary><p class="small muted">Strain totals overlap; combinations count each mouse once.</p>${combinations.length?`<ul class="chips" aria-label="Current genotype combinations" style="list-style:none;padding:0;margin:12px 0 0">${combinations.map(group=>`<li class="chip" aria-label="${esc(group.label)}: ${count(group.count)} mice"><span>${esc(group.label)}</span> <strong>${count(group.count)}</strong></li>`).join('')}</ul>`:'<p class="subtle">No current mice.</p>'}</details></section>`;
}
function breedingSummaryHTML(){
 const summary=summarizeBreeding(dataset,{asOf:localDate(),scope:breedingScope}),options=getBreedingOptions(dataset);
 const range=sex=>`${options[sex+'_min_weeks']}–${options[sex+'_max_weeks']} weeks`;
 const scopeLabel=breedingScope==='active'?'Active breeders':'All living mice';
 const items=[['total','Total breeding',scopeLabel,count(summary.total),summary.unknownSex?`${count(summary.unknownSex)} with unknown sex`:null],['male','Male','',count(summary.male)],['female','Female','',count(summary.female)],['maleFertile','Male in fertile age',range('male'),count(summary.maleFertile),summary.unknownMaleAge?`${count(summary.unknownMaleAge)} age unknown`:null],['femaleFertile','Female in fertile age',range('female'),count(summary.femaleFertile),summary.unknownFemaleAge?`${count(summary.unknownFemaleAge)} age unknown`:null],['genotyped','Genotyped / all mice','Clear recorded genotype',`${count(summary.genotyped)} / ${count(summary.total)}`]];
 return `<section class="mouse-summary breeding-summary" aria-labelledby="breeding-summary-heading"><div class="mouse-summary-heading"><h2 id="breeding-summary-heading">Current breeding colony <span>· ${count(summary.groupEstimate.totalGroups)} estimated current ${summary.groupEstimate.totalGroups===1?'group':'groups'}</span></h2><div class="actions"><label class="sr-only" for="breeding-scope">Breeding summary population</label><select id="breeding-scope"><option value="living"${breedingScope==='living'?' selected':''}>All living mice</option><option value="active"${breedingScope==='active'?' selected':''}>Active breeders</option></select>${button('Options','breeding-options')}<button class="text-button" data-action="breeding-help" aria-label="Help with breeding counts">Help</button></div></div><p class="small muted">${count(summary.groupEstimate.currentCageCount)} mixed-sex cages · ${count(summary.groupEstimate.sourceGroups.length)} additional Animal Sheet groups · ${count(summary.groupEstimate.sourceConflicts.length)} source conflicts to review${summary.groupEstimate.unresolvedRegisteredGroups.length?` · ${count(summary.groupEstimate.unresolvedRegisteredGroups.length)} historical registrations without a current cage match`:''}</p>${getBreedingOptionsStatus(dataset)==='invalid'?'<p class="alert error" role="alert">Saved age options could not be used. Default ranges are shown; review Options.</p>':''}<dl class="mouse-summary-grid breeding-summary-grid">${items.map(([key,label,note,total,unknown])=>`<div class="mouse-summary-item${key==='total'?' mouse-summary-total':''}" data-breeding-count="${key}"><dt>${esc(label)}${note?`<span>${esc(note)}</span>`:''}</dt><dd>${esc(total)}</dd>${unknown?`<span class="mouse-count-uncertain">${esc(unknown)}</span>`:''}</div>`).join('')}</dl></section>`;
}
