 let dialog=$('breeding-options-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='breeding-options-dialog';document.body.appendChild(dialog)}
 dialog.innerHTML='<div class="dialog-heading"><h2>Breeding options</h2><button class="icon-button" id="breeding-options-close" aria-label="Close breeding options">×</button></div><div class="dialog-content" id="breeding-options-content"></div>';
